const focusCost = (root, { focusCount }) => Math.min(focusCount,
  Math.max(0, Math.floor(Number(root.querySelector("[name=aimFocus]").value) || 0)));
return {
  attack: {
    hook: "attackOptions",
    run: () => ({
      dialogHtml: () => "<div class='form-group'><label>Aim For the Head: spend Focus for +1/+1 each</label><input type='number' name='aimFocus' min='0' value='0'></div>",
      focusCost,
      prepare(root, ctx) {
        const aim = root.querySelector("[name=aimFocus]");
        aim.max = ctx.focusCount;
        aim.disabled = ctx.focusCount <= 0;
        aim.addEventListener("input", ctx.updateFocusCost);
      },
      damageBonus(root, actor, state) {
        const spend = focusCost(root, state);
        if (!spend) return;
        state.damageResolve += spend;
        state.damageWounds += spend;
        state.cardLines.push("<div><strong>Aim For the Head:</strong> spent " + spend + " Focus for +" + spend + "/+" + spend + " damage.</div>");
      },
    }),
  },
};
